// original source for hash : https://www.shadertoy.com/view/4lXyWN
const uint k = 1103515245U;  // GLIB C
//const uint k = 134775813U;   // Delphi and Turbo Pascal
//const uint k = 1664525U;     // Numerical Recipes

vec3 hash( uvec3 x )
{
    //I think the value of x is usually comes from 2D/3D coordinates or time in most of applications.
    //These values are small and continuous.
    //So, multiply large prime value first.
    x*=k;
    //mix x, y, z values.
    //Without shift operator, x, y and z value become same value.
    x = ((x>>2u)^(x.yzx>>1u)^x.zxy)*k;

    return vec3(x)*(1.0/float(0xffffffffU));
}
vec4 disk(vec2 uv, vec2 pos, float rad, vec3 color) {
	float d = length(pos - uv) - rad;
	float t = clamp(d, 0.0, 1.0);
	return vec4(color, 1.0 - t);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor=  vec4(1., 1., 1., 1.0);

    // 
    float lineWidth = 0.005;
    float lineSpacing = 0.1;

    // uv座標を計算
    vec2 uv = fragCoord.xy / iResolution.xy;
    // normalize
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float y = mod(uv.y, lineSpacing);
    if (y <= lineWidth)
    {
        // 罫線を描画
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    // 横方向の罫線を描画する位置を計算
    float x = mod(uv.x, lineSpacing);
    if (x <= lineWidth)
    {
        // 罫線を描画
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }    



    float dist = length(uv - vec2(0.0, 0.0));

    // 円の直径
    float diameter = 0.75;

    uvec3 p = uvec3(fragCoord, iFrame);
    vec3 h = hash(p);
    float sampling = h.x + h.y + h.z;
    sampling = (sampling > 3.*0.5) ? 1.:0.;
    vec3 color = vec3(1.,1.,1.);
    color *= sampling;

    if (dist <= diameter)
    {
        // サンプリングを描画
       fragColor = vec4(color, 1.0);

    }

}
